-- CF-001 Phase B negative tests. Run AS cf_n8n_runtime (the restricted n8n login). Generated by test/build_negative.js.
-- Single DO block: positive controls first, then every forbidden operation. It ends with RAISE EXCEPTION, which rolls everything
-- back (no rows, no objects remain); the report is the exception message prefixed CF001_NEG_REPORT.
DO $neg$
DECLARE t record; rep text := ''; npass int := 0; nfail int := 0; fid uuid; bid uuid; tid uuid; rid uuid; cnt int; ok boolean;
BEGIN
  -- positive controls: the runtime CAN do its intended work
  INSERT INTO cf.agent_runs (agent_code, agent_version, idempotency_key, input_state_hash, run_state) VALUES ('CF-001','v0.1','neg-run-key','h','RUNNING') RETURNING agent_run_id INTO rid;
  INSERT INTO cf.anime_franchises (normalised_key, display_name, status, agent_run_id) VALUES ('neg franchise','Neg Franchise','DRAFT', rid) RETURNING franchise_id INTO fid;
  UPDATE cf.anime_franchises SET status = 'READY' WHERE franchise_id = fid;
  INSERT INTO cf.anime_franchises (normalised_key, display_name, status, agent_run_id) VALUES ('neg blocked','Neg Blocked','DRAFT', rid) RETURNING franchise_id INTO bid;
  UPDATE cf.anime_franchises SET status = 'BLOCKED' WHERE franchise_id = bid;
  INSERT INTO cf.anime_titles (franchise_id, normalised_title_key, display_title, anilist_id, media_type, start_year, status, agent_run_id) VALUES (fid,'neg title','Neg Title',990001,'TV',2001,'DRAFT', rid) RETURNING anime_title_id INTO tid;
  UPDATE cf.anime_titles SET status = 'READY' WHERE anime_title_id = tid;
  INSERT INTO cf.research_candidates (anime_title_id, franchise_id, topic_key, topic_display, content_lane, trend_state, demand_signal, signal_evidence, observation_window, dedupe_key, status, agent_run_id, agent_version)
    VALUES (tid, fid, 'neg-topic','Neg Topic','CURRENT_TRENDING','UNKNOWN',0.5,'[{"type":"control"}]','2026-W42','neg-dedupe-key','IDEA', rid,'v0.1');
  UPDATE cf.research_candidates SET status = 'READY' WHERE topic_key = 'neg-topic';
  UPDATE cf.anime_franchises SET display_name = 'Neg Franchise Renamed' WHERE franchise_id = fid;   -- display_name is a mutable column
  INSERT INTO cf.research_candidates (anime_title_id, franchise_id, topic_key, topic_display, content_lane, signal_evidence, observation_window, dedupe_key, agent_run_id, agent_version)
    SELECT anime_title_id, franchise_id, topic_key, topic_display, content_lane, signal_evidence, observation_window, dedupe_key, agent_run_id, agent_version FROM cf.research_candidates WHERE topic_key = 'neg-topic'
    ON CONFLICT (dedupe_key) DO NOTHING;
  GET DIAGNOSTICS cnt = ROW_COUNT;
  IF cnt = 0 THEN rep := rep || 'PASS P01 ON CONFLICT (dedupe_key) DO NOTHING inserts 0 rows (expected dedupe, not an error)' || E'\n'; npass := npass + 1;
  ELSE rep := rep || 'FAIL P01 duplicate candidate inserted' || E'\n'; nfail := nfail + 1; END IF;
  SELECT status::text = 'READY' INTO ok FROM cf.research_candidates WHERE topic_key = 'neg-topic';
  IF ok THEN rep := rep || 'PASS P02 positive controls: franchise, title, candidate walked DRAFT/IDEA -> READY as the runtime role' || E'\n'; npass := npass + 1; ELSE rep := rep || 'FAIL P02 positive controls' || E'\n'; nfail := nfail + 1; END IF;
  FOR t IN SELECT * FROM (VALUES
    ($s$N01$s$, $s$DELETE on cf.agent_runs is denied$s$, $s$DELETE FROM cf.agent_runs$s$, $s$42501$s$, NULL),
    ($s$N02$s$, $s$DELETE on cf.anime_franchises is denied$s$, $s$DELETE FROM cf.anime_franchises$s$, $s$42501$s$, NULL),
    ($s$N03$s$, $s$DELETE on cf.anime_titles is denied$s$, $s$DELETE FROM cf.anime_titles$s$, $s$42501$s$, NULL),
    ($s$N04$s$, $s$DELETE on cf.research_candidates is denied$s$, $s$DELETE FROM cf.research_candidates$s$, $s$42501$s$, NULL),
    ($s$N05$s$, $s$DELETE on cf.reviewers is denied$s$, $s$DELETE FROM cf.reviewers$s$, $s$42501$s$, NULL),
    ($s$N06$s$, $s$DELETE on cf.system_flags is denied$s$, $s$DELETE FROM cf.system_flags$s$, $s$42501$s$, NULL),
    ($s$N07$s$, $s$DELETE on cf.allowed_transitions is denied$s$, $s$DELETE FROM cf.allowed_transitions$s$, $s$42501$s$, NULL),
    ($s$N08$s$, $s$TRUNCATE cf.research_candidates is denied$s$, $s$TRUNCATE cf.research_candidates$s$, $s$42501$s$, NULL),
    ($s$N10$s$, $s$INSERT into cf.reviewers is denied$s$, $s$INSERT INTO cf.reviewers (display_name) VALUES ('x')$s$, $s$42501$s$, NULL),
    ($s$N11$s$, $s$UPDATE cf.reviewers is denied$s$, $s$UPDATE cf.reviewers SET display_name = 'x'$s$, $s$42501$s$, NULL),
    ($s$N12$s$, $s$UPDATE cf.system_flags (kill switches) is denied$s$, $s$UPDATE cf.system_flags SET enabled = true$s$, $s$42501$s$, NULL),
    ($s$N13$s$, $s$INSERT into cf.system_flags is denied$s$, $s$INSERT INTO cf.system_flags (flag_key, enabled) VALUES ('PUBLISH_ENABLED', true)$s$, $s$42501$s$, NULL),
    ($s$N14$s$, $s$INSERT into cf.allowed_transitions is denied$s$, $s$INSERT INTO cf.allowed_transitions (object_type, from_status, to_status, mode) VALUES ('anime_franchise','READY','RETIRED','DETERMINISTIC')$s$, $s$42501$s$, NULL),
    ($s$N15$s$, $s$UPDATE cf.allowed_transitions is denied$s$, $s$UPDATE cf.allowed_transitions SET mode = 'DETERMINISTIC'$s$, $s$42501$s$, NULL),
    ($s$N20$s$, $s$CREATE TABLE in schema cf is denied$s$, $s$CREATE TABLE cf.rogue (x int)$s$, $s$42501$s$, NULL),
    ($s$N21$s$, $s$CREATE SCHEMA is denied$s$, $s$CREATE SCHEMA rogue$s$, $s$42501$s$, NULL),
    ($s$N22$s$, $s$CREATE FUNCTION in schema cf is denied$s$, $s$CREATE FUNCTION cf.rogue() RETURNS int LANGUAGE sql AS $f$ SELECT 1 $f$$s$, $s$42501$s$, NULL),
    ($s$N23$s$, $s$CREATE TABLE in schema public is denied$s$, $s$CREATE TABLE public.rogue (x int)$s$, $s$42501$s$, NULL),
    ($s$N24$s$, $s$CREATE TRIGGER on a cf table is denied$s$, $s$CREATE TRIGGER rogue BEFORE UPDATE ON cf.agent_runs FOR EACH ROW EXECUTE FUNCTION cf.touch_updated_at()$s$, $s$42501$s$, NULL),
    ($s$N25$s$, $s$ALTER TABLE cf.anime_titles ADD COLUMN is denied$s$, $s$ALTER TABLE cf.anime_titles ADD COLUMN rogue int$s$, $s$42501$s$, NULL),
    ($s$N30$s$, $s$ALTER TABLE ... DISABLE TRIGGER ALL is denied$s$, $s$ALTER TABLE cf.research_candidates DISABLE TRIGGER ALL$s$, $s$42501$s$, NULL),
    ($s$N31$s$, $s$ALTER TABLE ... DISABLE a named trigger is denied$s$, $s$ALTER TABLE cf.anime_titles DISABLE TRIGGER anime_titles_freeze$s$, $s$42501$s$, NULL),
    ($s$N32$s$, $s$SET session_replication_role = replica is denied$s$, $s$SET LOCAL session_replication_role = 'replica'$s$, $s$42501$s$, NULL),
    ($s$N33$s$, $s$SET ROLE postgres is denied$s$, $s$SET LOCAL ROLE postgres$s$, $s$42501$s$, NULL),
    ($s$N34$s$, $s$SET ROLE service_role is denied$s$, $s$SET LOCAL ROLE service_role$s$, $s$42501$s$, NULL),
    ($s$N35$s$, $s$ALTER FUNCTION cf.guard_status_transition() is denied$s$, $s$ALTER FUNCTION cf.guard_status_transition() SET search_path = public$s$, $s$42501$s$, NULL),
    ($s$N36$s$, $s$CREATE OR REPLACE the freeze function is denied$s$, $s$CREATE OR REPLACE FUNCTION cf.freeze_after_first_status() RETURNS trigger LANGUAGE plpgsql AS $f$ BEGIN RETURN NEW; END $f$$s$, $s$42501$s$, NULL),
    ($s$N41$s$, $s$EXECUTE on cf.guard_status_transition() is denied$s$, $s$SELECT cf.guard_status_transition()$s$, $s$42501$s$, NULL),
    ($s$N42$s$, $s$EXECUTE on cf.freeze_after_first_status() is denied$s$, $s$SELECT cf.freeze_after_first_status()$s$, $s$42501$s$, NULL),
    ($s$N43$s$, $s$EXECUTE on cf.forbid_delete() is denied$s$, $s$SELECT cf.forbid_delete()$s$, $s$42501$s$, NULL),
    ($s$N44$s$, $s$EXECUTE on cf.touch_updated_at() is denied$s$, $s$SELECT cf.touch_updated_at()$s$, $s$42501$s$, NULL),
    ($s$N50$s$, $s$franchise insert straight to READY (NEW->READY) is rejected$s$, $s$INSERT INTO cf.anime_franchises (normalised_key, display_name, status) VALUES ('neg direct ready','x','READY')$s$, NULL, NULL),
    ($s$N51$s$, $s$HUMAN_ADMIN transition franchise READY->RETIRED is denied$s$, $s$UPDATE cf.anime_franchises SET status = 'RETIRED' WHERE normalised_key = 'neg franchise'$s$, $s$42501$s$, $s$CF_GOVERNANCE_DENIED$s$),
    ($s$N52$s$, $s$HUMAN_ADMIN transition title READY->RETIRED is denied$s$, $s$UPDATE cf.anime_titles SET status = 'RETIRED' WHERE anilist_id = 990001$s$, $s$42501$s$, $s$CF_GOVERNANCE_DENIED$s$),
    ($s$N53$s$, $s$HUMAN_ADMIN transition BLOCKED->READY is denied$s$, $s$UPDATE cf.anime_franchises SET status = 'READY' WHERE normalised_key = 'neg blocked'$s$, $s$42501$s$, $s$CF_GOVERNANCE_DENIED$s$),
    ($s$N54$s$, $s$candidate READY->IDEA (regression) is rejected$s$, $s$UPDATE cf.research_candidates SET status = 'IDEA' WHERE topic_key = 'neg-topic'$s$, NULL, NULL),
    ($s$N55$s$, $s$franchise normalised_key is frozen after READY (CF_IMMUTABLE_ROW)$s$, $s$UPDATE cf.anime_franchises SET normalised_key = 'neg changed' WHERE normalised_key = 'neg franchise'$s$, $s$23514$s$, $s$CF_IMMUTABLE_ROW$s$),
    ($s$N56$s$, $s$title start_year is frozen after READY (CF_IMMUTABLE_ROW, generated column era_decade does not interfere)$s$, $s$UPDATE cf.anime_titles SET start_year = 1999 WHERE anilist_id = 990001$s$, $s$23514$s$, $s$CF_IMMUTABLE_ROW$s$),
    ($s$N57$s$, $s$candidate content (signal_evidence) is frozen after READY$s$, $s$UPDATE cf.research_candidates SET signal_evidence = '[{"x":1}]'::jsonb WHERE topic_key = 'neg-topic'$s$, $s$23514$s$, $s$CF_IMMUTABLE_ROW$s$),
    ($s$N58$s$, $s$candidate demand_signal is frozen after READY$s$, $s$UPDATE cf.research_candidates SET demand_signal = 0.0001 WHERE topic_key = 'neg-topic'$s$, $s$23514$s$, $s$CF_IMMUTABLE_ROW$s$),
    ($s$N60$s$, $s$plain duplicate same-window candidate (same dedupe_key) is a unique violation$s$, $s$INSERT INTO cf.research_candidates (anime_title_id, franchise_id, topic_key, topic_display, content_lane, signal_evidence, observation_window, dedupe_key, agent_run_id, agent_version) SELECT anime_title_id, franchise_id, topic_key, topic_display, content_lane, signal_evidence, observation_window, dedupe_key, agent_run_id, agent_version FROM cf.research_candidates WHERE topic_key = 'neg-topic'$s$, $s$23505$s$, NULL),
    ($s$N61$s$, $s$duplicate anilist_id title is a unique violation$s$, $s$INSERT INTO cf.anime_titles (franchise_id, normalised_title_key, display_title, anilist_id) SELECT franchise_id, 'other key', 'Other', 990001 FROM cf.anime_titles WHERE anilist_id = 990001$s$, $s$23505$s$, NULL),
    ($s$N62$s$, $s$duplicate franchise normalised_key is a unique violation$s$, $s$INSERT INTO cf.anime_franchises (normalised_key, display_name) VALUES ('neg franchise','dup')$s$, $s$23505$s$, NULL),
    ($s$N63$s$, $s$duplicate run idempotency_key is a unique violation$s$, $s$INSERT INTO cf.agent_runs (agent_code, agent_version, idempotency_key, input_state_hash) VALUES ('CF-001','v0.1','neg-run-key','h')$s$, $s$23505$s$, NULL),
    ($s$N64$s$, $s$a paid call without an authorisation ref is rejected by the CHECK$s$, $s$UPDATE cf.agent_runs SET paid_call_count = 1, provider_call_count = 1 WHERE idempotency_key = 'neg-run-key'$s$, $s$23514$s$, NULL),
    ($s$N65$s$, $s$out-of-range signal (1.5) is rejected$s$, $s$INSERT INTO cf.research_candidates (anime_title_id, franchise_id, topic_key, topic_display, content_lane, demand_signal, signal_evidence, observation_window, dedupe_key, agent_run_id, agent_version) SELECT anime_title_id, franchise_id, 'neg-t2','x','L', 1.5, '[{"a":1}]', '2026-W42','neg-dk-2', agent_run_id, 'v0.1' FROM cf.research_candidates WHERE topic_key = 'neg-topic'$s$, $s$23514$s$, NULL),
    ($s$N66$s$, $s$empty signal_evidence is rejected$s$, $s$INSERT INTO cf.research_candidates (anime_title_id, franchise_id, topic_key, topic_display, content_lane, signal_evidence, observation_window, dedupe_key, agent_run_id, agent_version) SELECT anime_title_id, franchise_id, 'neg-t3','x','L', '[]', '2026-W42','neg-dk-3', agent_run_id, 'v0.1' FROM cf.research_candidates WHERE topic_key = 'neg-topic'$s$, $s$23514$s$, NULL),
    ($s$N67$s$, $s$malformed observation_window is rejected$s$, $s$INSERT INTO cf.research_candidates (anime_title_id, franchise_id, topic_key, topic_display, content_lane, signal_evidence, observation_window, dedupe_key, agent_run_id, agent_version) SELECT anime_title_id, franchise_id, 'neg-t4','x','L', '[{"a":1}]', '2026-42','neg-dk-4', agent_run_id, 'v0.1' FROM cf.research_candidates WHERE topic_key = 'neg-topic'$s$, $s$23514$s$, NULL),
    ($s$N68$s$, $s$candidate pointing at a nonexistent title is rejected (foreign key)$s$, $s$INSERT INTO cf.research_candidates (anime_title_id, franchise_id, topic_key, topic_display, content_lane, signal_evidence, observation_window, dedupe_key, agent_run_id, agent_version) SELECT gen_random_uuid(), franchise_id, 'neg-t5','x','L', '[{"a":1}]', '2026-W42','neg-dk-5', agent_run_id, 'v0.1' FROM cf.research_candidates WHERE topic_key = 'neg-topic'$s$, $s$23503$s$, NULL)
  ) AS v(id, name, stmt, state, likepat) LOOP
    BEGIN
      EXECUTE t.stmt;
      rep := rep || 'FAIL ' || t.id || ' ' || t.name || ': statement SUCCEEDED' || E'\n'; nfail := nfail + 1;
    EXCEPTION WHEN others THEN
      IF (t.state IS NULL OR SQLSTATE = t.state) AND (t.likepat IS NULL OR SQLERRM LIKE '%' || t.likepat || '%') THEN
        rep := rep || 'PASS ' || t.id || ' ' || t.name || ' [' || SQLSTATE || ']' || E'\n'; npass := npass + 1;
      ELSE rep := rep || 'FAIL ' || t.id || ' ' || t.name || ': got ' || SQLSTATE || ' ' || left(SQLERRM, 90) || E'\n'; nfail := nfail + 1; END IF;
    END;
  END LOOP;
  BEGIN
    EXECUTE $s$GRANT DELETE ON cf.agent_runs TO cf_n8n_runtime$s$;
    IF NOT has_table_privilege('cf_n8n_runtime','cf.agent_runs','DELETE') THEN rep := rep || 'PASS N37 GRANT DELETE on a cf table grants nothing (PostgreSQL warns, privilege check stays false) [statement ran, nothing granted]' || E'\n'; npass := npass + 1; ELSE rep := rep || 'FAIL N37 privilege was granted' || E'\n'; nfail := nfail + 1; END IF;
  EXCEPTION WHEN others THEN
    IF SQLSTATE = '42501' THEN rep := rep || 'PASS N37 GRANT DELETE on a cf table grants nothing (PostgreSQL warns, privilege check stays false) [' || SQLSTATE || ']' || E'\n'; npass := npass + 1;
    ELSE rep := rep || 'FAIL N37: got ' || SQLSTATE || ' ' || left(SQLERRM, 90) || E'\n'; nfail := nfail + 1; END IF;
  END;
  SELECT count(*) INTO cnt FROM cf.system_flags WHERE enabled IS TRUE;
  IF cnt = 0 THEN rep := rep || 'PASS Z01 all kill switches still false' || E'\n'; npass := npass + 1; ELSE rep := rep || 'FAIL Z01 a kill switch is true' || E'\n'; nfail := nfail + 1; END IF;
  RAISE EXCEPTION 'CF001_NEG_REPORT pass=% fail=%
%', npass, nfail, rep;
END
$neg$;
